"""Minimal, privacy-conscious client for OpenAI's Responses API.

This module uses only Python's standard library.  Set ``OPENAI_API_KEY`` in
the environment, then call ``send_prompt`` or create an ``OpenAIClient``.
Prompts and API keys are never logged, and requests default to ``store=false``.
"""

from __future__ import annotations

import json
import os
import socket
import urllib.error
import urllib.request
from dataclasses import dataclass
from typing import Any, Mapping


DEFAULT_ENDPOINT = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-5-mini"


class OpenAIError(RuntimeError):
    """An error returned by OpenAI or encountered while calling the API."""

    def __init__(self, message: str, *, status: int | None = None) -> None:
        super().__init__(message)
        self.status = status


def _error_message(data: Any, fallback: str) -> str:
    if isinstance(data, Mapping):
        error = data.get("error")
        if isinstance(error, Mapping) and isinstance(error.get("message"), str):
            return error["message"]
    return fallback


def _output_text(response: Mapping[str, Any]) -> str:
    # Some API responses include this convenience field.
    direct = response.get("output_text")
    if isinstance(direct, str):
        return direct

    parts: list[str] = []
    output = response.get("output", [])
    if isinstance(output, list):
        for item in output:
            if not isinstance(item, Mapping) or item.get("type") != "message":
                continue
            content = item.get("content", [])
            if not isinstance(content, list):
                continue
            for part in content:
                if (
                    isinstance(part, Mapping)
                    and part.get("type") == "output_text"
                    and isinstance(part.get("text"), str)
                ):
                    parts.append(part["text"])
    return "".join(parts)


@dataclass(frozen=True)
class OpenAIClient:
    """Small synchronous client for text prompts sent to Responses API."""

    api_key: str | None = None
    model: str = DEFAULT_MODEL
    endpoint: str = DEFAULT_ENDPOINT
    timeout: float = 60.0
    organization: str | None = None
    project: str | None = None

    def _key(self) -> str:
        key = self.api_key or os.environ.get("OPENAI_API_KEY")
        if not key:
            raise OpenAIError(
                "Missing API key: set OPENAI_API_KEY or pass api_key explicitly."
            )
        return key

    def create_response(
        self,
        prompt: str,
        *,
        instructions: str | None = None,
        max_output_tokens: int | None = None,
    ) -> dict[str, Any]:
        """Send a private text prompt and return the complete decoded response."""
        if not isinstance(prompt, str) or not prompt:
            raise ValueError("prompt must be a non-empty string")
        if max_output_tokens is not None and max_output_tokens <= 0:
            raise ValueError("max_output_tokens must be positive")

        payload: dict[str, Any] = {
            "model": self.model,
            "input": prompt,
            "store": False,
        }
        if instructions is not None:
            payload["instructions"] = instructions
        if max_output_tokens is not None:
            payload["max_output_tokens"] = max_output_tokens

        headers = {
            "Authorization": f"Bearer {self._key()}",
            "Content-Type": "application/json",
        }
        if self.organization:
            headers["OpenAI-Organization"] = self.organization
        if self.project:
            headers["OpenAI-Project"] = self.project

        request = urllib.request.Request(
            self.endpoint,
            data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
            headers=headers,
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as reply:
                raw = reply.read()
        except urllib.error.HTTPError as exc:
            raw = exc.read()
            try:
                data = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                data = None
            message = _error_message(data, f"OpenAI API returned HTTP {exc.code}")
            raise OpenAIError(message, status=exc.code) from exc
        except (urllib.error.URLError, socket.timeout, TimeoutError) as exc:
            reason = getattr(exc, "reason", exc)
            raise OpenAIError(f"Could not reach OpenAI: {reason}") from exc

        try:
            result = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise OpenAIError("OpenAI returned an invalid JSON response") from exc
        if not isinstance(result, dict):
            raise OpenAIError("OpenAI returned an unexpected response shape")
        return result

    def send_prompt(
        self,
        prompt: str,
        *,
        instructions: str | None = None,
        max_output_tokens: int | None = None,
    ) -> str:
        """Send a prompt and return its combined text output."""
        response = self.create_response(
            prompt,
            instructions=instructions,
            max_output_tokens=max_output_tokens,
        )
        text = _output_text(response)
        if not text:
            raise OpenAIError("The response contained no text output")
        return text


def send_prompt(
    prompt: str,
    *,
    model: str = DEFAULT_MODEL,
    api_key: str | None = None,
    instructions: str | None = None,
    max_output_tokens: int | None = None,
    timeout: float = 60.0,
) -> str:
    """Convenience function that sends one prompt and returns text output."""
    return OpenAIClient(
        api_key=api_key,
        model=model,
        timeout=timeout,
    ).send_prompt(
        prompt,
        instructions=instructions,
        max_output_tokens=max_output_tokens,
    )


__all__ = ["OpenAIClient", "OpenAIError", "send_prompt"]
